INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (0, 0, "隠し立てなど、そんな。", 107611, 11, 10, 1, 0, 0.5, 905, 19050056);
