INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (0, 0, "はぁ、レイ様…♡\n流れる姿も麗しいですね。\nずっと見ていられるぅ…", 117411, 11, 7, 1, 0, 1, 943, 19430034);
