INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (0, 0, "こんなに人がいっぱいいる商機、\n見逃すわけにはいかないにゃ！", 107911, 11, 10, 1, 0, 1, 944, 19440038);
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES ("", "", "", 0, 91, "", "", "", "", 944, 19440039);
