INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (0, 0, "それ、アキノさんの許可とってるの？\nもし無許可だったら怒られるわよ？", 126811, 11, 7, 1, 0, 1, 944, 19440043);
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES ("", "", "", 0, 91, "", "", "", "", 944, 19440044);
