INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (0, 0, "大丈夫にゃ。バレないように…\nってやばいにゃ！　見回りだにゃ！", 107911, 11, 8, 1, 0, 0.5, 944, 19440046);
