INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (0.1, 0.1, "45_yui_shy_in", 122611, 3, 0, "45_yui_shy_loop", 1, "", 945, 19450030);
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (0.1, 0.1, "45_yui_shy_in", 1, 3, 0, "45_yui_shy_loop", 1, "", 945, 19450031);
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES ("", "", "vo_fpc_30504", "vo_fpc", 21, "", 0, "", "", 945, 19450032);
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (0, 0, "…うん、やっちゃった…\nおっきなハートマーク…\nやっぱりこれは無しで！\nマコトちゃん食べてくれる！？", 122611, 11, 5, 1, 0, 1, 945, 19450033);
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES ("", "", "", 0, 91, "", "", "", "", 945, 19450034);
